pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the 'from' address, a uint value, and an array length (we'll build the array)
    function testFuzz_property(address from, uint256 v, uint256 tosLen) public {
        // keep tosLen reasonable but allow zero to be excluded by require in C
        tosLen = bound(tosLen, 0, 8);

        // deploy a benign callee that always returns true for transferFrom
        CalleeSucceeds cal = new CalleeSucceeds();

        // build _tos array with tosLen entries, using distinct addresses derived from 'from' to vary inputs
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) {
            // derive addresses deterministically but varied
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i)))));
        }

        // Call and capture whether call completed (didn't revert) and the returned bool
        bool ok;
        bool ret;
        if (tosLen == 0) {
            // If tos is empty, the reference contract reverts due to require; reflect that via try/catch
            try c.transfer(from, address(cal), tos, v) returns (bool r) { ok = true; ret = r; } catch { ok = false; ret = false; }
            // For empty _tos the reference reverts, so we only assert the general rule on admissible inputs.
            // We therefore short-circuit by asserting true (no-op) via a check on ok==false allowed here.
            // But as per constraints we must make a single assertTrue observing c; use ok==false for this branch.
            assertTrue(ok == false);
            return;
        }

        // For non-empty _tos, the reference executes calls to cal which always succeed; so transfer should complete and return true.
        try c.transfer(from, address(cal), tos, v) returns (bool r) { ok = true; ret = r; } catch { ok = false; ret = false; }

        // Single assertion: for all admissible inputs (non-empty _tos where cal succeeds), C.transfer returns true (ok==true and ret==true)
        assertTrue(ok && ret == true);
    }
}

// A minimal adversarial counterpart that behaves as a successful callee for transferFrom
contract CalleeSucceeds {
    // implement a fallback that matches the selector and returns true for the low-level call
    fallback() external payable {
        // simply return true (no data) — low-level call in C only checks success boolean, not returned data
    }
}

