pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: an address 'from' (actor) and an uint256 value and an array length seed
    function testFuzz_property(address from, uint96 v, uint8 tosLenSeed) public {
        // Keep domain wide but sensible
        vm.assume(from != address(0));
        uint8 len = uint8(bound(tosLenSeed, 1, 5)); // ensure at least one recipient

        // deploy adversarial callee that will try to mutate its own state on transferFrom
        AttackerReceiver ar = new AttackerReceiver();

        // prepare tos array filled with the attacker address
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(ar);

        // Make sure attacker has some ETH if needed (not needed here but harmless)
        vm.deal(from, 1 ether);

        // Drive the call: we call c.transfer which will low-level call/staticcall into ar
        bool ok;
        try c.transfer(from, address(ar), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property we assert: in the correct contract, the callee's state change
        // (its counter incremented by transferFrom) must have been allowed, so the callee's
        // public counter should be equal to len. The buggy variant using staticcall will
        // prevent that state change for some inputs, so this assertion will fail against the mutant.
        assertTrue(ar.counter() == len);
    }
}

// Adversarial helper: exposes transferFrom which increments its counter when called
contract AttackerReceiver {
    uint public counter;
    // match selector transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external returns (bool) {
        // mutate state
        counter += 1;
        return true;
    }
}

