// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the from address and an array length + single recipient value; the fuzzer will craft addresses
    // We model the external callee as a helper that records how many times it was called and which indices
    function testFuzz_property(address from, address filler, uint8 n) public {
        // Keep length within reasonable range but allow zero-length to be excluded by require in transfer
        uint len = uint(bound(n, 1, 8)); // ensure at least 1 element to satisfy require(_tos.length > 0)

        // Build dynamic array of addresses where index 0 is distinct so skipping it is observable
        address[] memory tos = new address[](len);
        // Make tos[0] distinct from others using `filler` and `from` so it's observable
        tos[0] = address(uint160(uint(keccak256(abi.encodePacked(filler, uint256(0))))));
        for (uint i = 1; i < len; i++) {
            // fill other entries deterministically but differently
            tos[i] = address(uint160(uint(keccak256(abi.encodePacked(filler, i)))));
        }

        // Deploy a helper callee that implements transferFrom signature and increments a counter
        CalleeHelper helper = new CalleeHelper();

        // call C.transfer with helper address so C will low-level call helper
        bool ok;
        try c.transfer(from, address(helper), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference implementation always calls transferFrom for EVERY index including 0,
        // therefore the helper's seenCount must equal tos.length (for all valid inputs).
        // The mutant skipping index 0 will cause seenCount < tos.length when tos.length >= 1.
        assertTrue(helper.seenCount() == int(len));
    }
}

// Minimal adversarial helper that exposes transferFrom(address,address,uint256) and records calls.
contract CalleeHelper {
    int public seenCount = 0;

    // Define the expected selector and function signature to be called via low-level call
    function transferFrom(address, address, uint256) public returns (bool) {
        seenCount += 1;
        return true;
    }

    // fallback to handle low-level calls with selector (in case mutant uses exact selector encoding)
    fallback() external payable {
        // If called with proper selector for transferFrom, decode and count.
        // Attempt to decode selector and parameters; if matching, increment seenCount.
        bytes4 sel;
        assembly { sel := calldataload(0) }
        // selector for transferFrom(address,address,uint256)
        bytes4 expected = bytes4(keccak256("transferFrom(address,address,uint256)"));
        if (sel == expected) {
            // increment; ignore decoding details because presence of selector suffices
            seenCount += 1;
            // return true (ABI encoded)
            assembly {
                mstore(0x00, 0x01)
                return(0x00, 0x20)
            }
        }
        // otherwise do nothing
    }
}
